const MON: Record<string, string> = { ledna: 'January', února: 'February', března: 'March', dubna: 'April', května: 'May', června: 'June', července: 'July', srpna: 'August', září: 'September', října: 'October', listopadu: 'November', prosince: 'December' };
const WD: Record<string, string> = { pondělí: 'Monday', úterý: 'Tuesday', středa: 'Wednesday', čtvrtek: 'Thursday', pátek: 'Friday', sobota: 'Saturday', neděle: 'Sunday' };
const pl = (n: string, one: string, many: string) => (n === '1' ? one : many);
type R = [RegExp, string | ((m: RegExpMatchArray) => string)];
/** Anchored rules for whole strings with numbers/names. */
export const EN_RULES: R[] = [
  [/^(pondělí|úterý|středa|čtvrtek|pátek|sobota|neděle) (\d+)\. (\S+)$/i, (m) => `${WD[m[1].toLowerCase()]} ${m[2]} ${MON[m[3]] ?? m[3]}`],
  [/^Zbývá (\d+) (úkol|úkoly|úkolů)$/, (m) => `${m[1]} ${pl(m[1], 'task', 'tasks')} left`],
  [/^Hotovo (\d+) z (\d+)$/, 'Done $1 of $2'],
  [/^(\d+) z (\d+) hotovo$/, '$1 of $2 done'],
  [/^Dnes podáno (\d+) z (\d+)$/, 'Given today: $1 of $2'],
  [/^(\d+) po termínu$/, '$1 overdue'],
  [/^(.+): (\d+) (den|dny|dní) po termínu$/, (m) => `${m[1]}: ${m[2]} ${pl(m[2], 'day', 'days')} overdue`],
  [/^Odškrtnout: (.+)$/, (m) => `Tick off: ${tr(m[1])}`],
  [/^Vrátit: (.+)$/, (m) => `Undo: ${tr(m[1])}`],
  [/^Zavolat (.+)$/, 'Call $1'],
  [/^Pohladit (.+)$/, 'Pet $1'],
  [/^Živý mazlíček (.+?): (.+), péče (\d+) %$/, (m) => `Live pet ${m[1]}: ${tr(m[2])}, care ${m[3]}%`],
  [/^Výdaje po měsících v roce (\d+)$/, 'Expenses by month in $1'],
  [/^Platné od (.+)$/, (m) => `Valid from ${tr(m[1])}`],
  [/^Od (.+)$/, (m) => `From ${tr(m[1])}`],
  [/^Ukončeno (.+)$/, (m) => `Ended ${tr(m[1])}`],
  [/^Každých (\d+) dní$/, 'Every $1 days'],
  [/^každé (\d+) měsíce$/, 'every $1 months'],
  [/^Opakovat každých (\d+) (den|dní)$/, (m) => `Repeat every ${m[1]} ${pl(m[1], 'day', 'days')}`],
  [/^Uloženo z fotky: (\d+) \S+$/, (m) => `Saved from photo: ${m[1]} ${pl(m[1], 'record', 'records')}`],
  [/^Rok (\d+) v příběhu$/, 'Your $1 as a story'],
  [/^Tlapka Wrapped – (.+)$/, 'Tlapka Wrapped – $1'],
  [/^(\d+) (placená návštěva|placené návštěvy|placených návštěv)$/, (m) => `${m[1]} paid ${pl(m[1], 'visit', 'visits')}`],
  [/^([\d\s ]+(?:,\d+)?) Kč$/, (m) => `CZK ${m[1].trim()}`],
  [/^(\d+) (karta|karty|karet) · sdílené s domácností$/, (m) => `${m[1]} ${pl(m[1], 'card', 'cards')} · shared with household`],
  [/^Použito (\d+)×$/, 'Used $1×'],
  [/^Ukázat kartu (.+)$/, 'Show card $1'],
  [/^Načteno: (.+)$/, 'Scanned: $1'],
  [/^Náhled: (.+)$/, 'Preview: $1'],
  [/^Zatím jeden záznam: (.+) kg\. Přidej další pro graf\.$/, 'Only one entry so far: $1 kg. Add more for a chart.'],
  [/^Zdarma (\d+), s Premium kolik chceš$/, 'Free $1, as many as you like with Premium'],
  [/^(\d+) zkušební dotazy Aivetovi$/, '$1 trial questions for Aivet'],
  [/^Zdarma můžeš mít (\d+) mazlíčky$/, 'Free lets you have $1 pets'],
  [/^Dosáhl jsi limitu dotazů \((.+)\)\. Zkus to za (\d+) min\.$/, (m) => `You've hit the question limit (${tr(m[1])}). Try again in ${m[2]} min.`],
  [/^(.+) přidán(a?) ✓$/, '$1 added ✓'],
  [/^(.+) smazán(a?)$/, '$1 deleted'],
  [/^Díky za (.+)!$/, (m) => `Thanks for the ${tr(m[1])}!`],
  [/^(Spokojená|Spokojený)\. Pojď si hrát!$/, 'Content. Come play!'],
  [/^Předávací karta – (.+)$/, 'Handover card – $1'],
  [/^Zdravotní pas – (.+)$/, 'Health passport – $1'],
  [/^QR kód pasu – (.+)$/, 'Passport QR code – $1'],
  [/^Čip (\d+)$/, 'Chip $1'],
  [/^Venčení – (.+)$/, 'Walk – $1'],
  [/^(.+): venčení hotovo$/, '$1: walk done'],
  [/^(.+): (.+) hotovo$/, (m) => `${m[1]}: ${tr(m[2])} done`],
  [/^(.+): dávka zapsána ✓$/, '$1: dose logged ✓'],
  [/^(.+) – zapsáno (.+)$/, '$1 – logged $2'],
  [/^bezpečně znovu po (.+)$/, 'safe again after $1'],
  [/^Dle potřeby, nejdřív po (\d+) h$/, 'As needed, not before $1 h'],
  [/^Podle nastavení až (.+)\. Opravdu zapsat dávku\?$/, 'Per your settings not until $1. Log the dose anyway?'],
  [/^V den termínu v (\d+):00$/, 'On the due date at $1:00'],
  [/^Zálohováno (.+?) · (.+)$/, (m) => `Backed up ${m[1]} · ${tr(m[2])}`],
  [/^poslední synchronizace (.+)$/, 'last sync $1'],
  [/^(\S+) tarif · platí do (.+)$/, (m) => `${tr(m[1])} plan · valid until ${tr(m[2])}`],
  [/^Zítra: (.+)$/, (m) => `Tomorrow: ${tr(m[1])}`],
  [/^Připrav si (.+)\.$/, 'Have $1 ready.'],
  [/^Objevení výběhu (.+)$/, 'Discovered dog park $1'],
  [/^(\d+) dní léků v řadě bez vynechání$/, '$1 days of meds in a row without a miss'],
  [/^Hlavní role: (.+)\. Zatím (\d+) dní společné péče\.$/, (m) => `Lead role: ${tr(m[1])}. ${m[2]} days of care together so far.`],
  [/^Celý rok (\d+), hlavní role: (.+)\.$/, (m) => `All of ${m[1]}, lead role: ${tr(m[2])}.`],
  [/^Nejoblíbenější výběh: (.+)$/, (m) => `Favourite dog park: ${tr(m[1])}`],
  [/^Nejdelší série: (\d+) dní v řadě\.$/, 'Longest streak: $1 days in a row.'],
  [/^(\d+)× prevence včas \(odčervení, očkování, klíšťata\)\.$/, '$1× prevention on time (deworming, vaccination, ticks).'],
  [/^Nejčastěji: (.+)$/, 'Most often: $1'],
  [/^([+−])(.+) kg od (.+) kg\.$/, (m) => `${m[1]}${m[2].replace(',', '.')} kg from ${m[3].replace(',', '.')} kg.`],
  [/^To je (.+) Kč měsíčně – a stálo to za to\.$/, 'That is CZK $1 a month – and worth it.'],
  [/^(.+) zapsaných chvil péče\.$/, '$1 logged moments of care.'],
  [/^(.+) je$/, '$1 is'],
  [/^(.+) – (zatím letos|rok \d+) v Tlapce\. (.+)$/, (m) => `${m[1]} – ${m[2] === 'zatím letos' ? 'this year so far' : m[2].replace('rok', 'year')} in Tlapka. ${m[3]}`],
  [/^Kód (.+) \(zkopírováno\) platí do (.+)\. Partner ho zadá v Nastavení → Účet\.$/, 'Code $1 (copied) valid until $2. Your partner enters it in Settings → Account.'],
  [/^Platí 7 dní, bez registrace\. Zkopírováno:\s*(.+)$/, 'Valid 7 days, no sign-up. Copied: $1'],
  [/^Synchronizováno · (.+)$/, 'Synced · $1'],
  [/^(.+) · vygenerováno v aplikaci Tlapka (.+)$/, '$1 · generated in the Tlapka app $2'],
  [/^Hledám hlídání pro (.+)\. Tady je přehled péče:$/, (m) => `Looking for a sitter for ${m[1].replace(/ a /g, ' and ')}. Here's the care overview:`],
  [/^Předávací karta z aplikace Tlapka · (.+)$/, 'Handover card from the Tlapka app · $1'],
  [/^Bojí se \/ pozor: (.+)$/, 'Fears / watch out: $1'],
  [/^Záložní kontakt: (.+)$/, 'Backup contact: $1'],
  [/^Veterinář: (.+)$/, 'Vet: $1'],
  [/^Doporučení pro (.+)$/, (m) => `Recommended for ${tr(m[1])}`],
  [/^termín (.+)$/, 'due $1'],
  [/^✓ podal\(a\) (.+) v (.+)$/, '✓ given by $1 at $2'],
  [/^Importovat (.+)\?$/, 'Import $1?'],
];
/** Inline replacements applied inside longer strings (dates, ages, relative days). */
export const EN_INLINE: R[] = [
  [/(\d+)\. (\d+)\. (\d{4})/g, '$1/$2/$3'],
  [/\b(\d+)\. (\d+)\.(?!\d)/g, '$1/$2'],
  [/(\d+)\. (ledna|února|března|dubna|května|června|července|srpna|září|října|listopadu|prosince)/g, (m) => `${m[1]} ${MON[m[2]]}`],
  [/za (\d+) (den|dny|dní)/g, (m) => `in ${m[1]} ${pl(m[1], 'day', 'days')}`],
  [/před (\d+) (dnem|dny)/g, (m) => `${m[1]} ${pl(m[1], 'day', 'days')} ago`],
  [/(\d+) (rok|roky|let)\b/g, (m) => `${m[1]} ${pl(m[1], 'year', 'years')}`],
  [/(\d+) (měsíc|měsíce|měsíců)/g, (m) => `${m[1]} ${pl(m[1], 'month', 'months')}`],
  [/(\d+) (den|dny|dní)\b/g, (m) => `${m[1]} ${pl(m[1], 'day', 'days')}`],
  [/(\d+),(\d+) kg/g, '$1.$2 kg'],
  [/(\d+)× denně/g, '$1× a day'],
  [/\bdnes\b/g, 'today'], [/\bzítra\b/g, 'tomorrow'], [/\bvčera\b/g, 'yesterday'],
  [/\bprůměr\b/g, 'average'],
  [/(\d[\d\s\u00a0]*(?:,\d+)?) Kč/g, (m) => `CZK ${m[1].trim()}`],
];
